import {loadModule} from './modules.js';
import {authConfig} from './auth-config.js';
import {random,base64,unbase64,deriveKey,encryptJSON,decryptJSON,otp,parseProvisioning,validate,decodeBase32,sameAccount,exportPortable,importPortable} from './crypto.js';
const root=document.getElementById('root');
const icon=(name,size=22)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true">${({trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',qr:'<path d="M3 3h6v6H3zM15 3h6v6h-6zM3 15h6v6H3zM15 15h3v3h3v3h-6z"/>',shield:'<path d="M12 3l8 3v6c0 5-5 8-8 10-3-2-8-5-8-10V6z"/><path d="M8 12l3 3 5-6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 018 0v3"/>',plus:'<path d="M12 4v16M4 12h16"/>',close:'<path d="M6 6l12 12M6 18L18 6"/>',search:'<circle cx="10" cy="10" r="7"/><path d="M15 15l6 6"/>',folder:'<path d="M3 5h7l2 3h9v13H3z"/>',star:'<path d="M12 3l3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>',backup:'<path d="M4 7h16v14H4zM8 7V3h8v4M12 17V10M9 13l3-3 3 3"/>',sun:'<circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M1 12h2M21 12h2"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 2v4M12 18v4M2 12h4M18 12h4"/>',heart:'<path d="M3 12h4l3-7 4 14 3-7h4"/>',grid:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>',download:'<path d="M12 3v12M7 10l5 5 5-5M4 16v5h16v-5"/>'})[name]||'<path d="M5 12l4 4L19 6"/>'}</svg>`;
const brand=`<a class="brand" href="#home"><span class="brand-symbol">${icon('shield',25)}</span>sentinel<span class="brand-dot">.</span></a>`;
const escape=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let session=null,view='accounts',filter='All accounts',query='',busy=false,epoch=0,modal=null;
const prefs=()=>{try{return JSON.parse(localStorage.getItem('sentinel.preferences')||'{}');}catch{return {};}};
let theme=prefs().theme||'dark';document.documentElement.dataset.theme=theme;
const readEnvelope=()=>{try{const value=vaultRead();return value?JSON.parse(value):null;}catch{return {version:0,unavailable:true};}};
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4000);}
function landing(){root.innerHTML=`<div class="landing"><header class="site-header wrap">${brand}<nav><a href="#features">Features</a><a href="#recovery">Recovery</a><a href="#faq">Questions</a></nav><a class="text-link" href="#signin">Sign in</a><a class="button small dark" href="#vault">Open vault ${icon('lock',16)}</a></header><main><section class="hero wrap"><div class="hero-copy"><div class="eyebrow"><span class="tiny-pill">MEET SENTINEL</span> YOUR DIGITAL LIFE. UNDER YOUR CONTROL.</div><h1>Your codes.<br><span>Your rules.</span></h1><p>Your everyday accounts, organized and protected. Offline codes. Encrypted backups. One space that feels like yours.</p><div class="hero-actions"><a class="button dark" href="#vault">Open your vault ${icon('lock',18)}</a><button class="button demo-launch" data-demo>Try demo ${icon('chevron',18)}</button><a class="text-link" href="downloads/SentinelAuthenticator.apk" download>Get the Android app</a></div><div class="hero-notes"><span>✓ Local vault also available</span><span>✓ Encrypted on your device</span></div></div><div class="hero-display"><div class="orbit-emblem"><div class="orbit-ring">${icon('shield',74)}</div><span>PROTECTED BY DESIGN</span></div><div class="display-bar"><div class="mini-brand">${icon('shield',19)} Your everyday vault</div><span class="demo-badge">ILLUSTRATIVE PREVIEW</span></div>${[['Google','personal@example.test','482 916','purple'],['GitHub','work@example.test','073 258','navy']].map(([service,label,code,color])=>`<div class="preview-card"><div class="account-line"><span class="service-avatar ${color}">${service[0]}</span><div><strong>${service}</strong><small>${label}</small></div>${icon('star',17)}</div><div class="preview-code">${code}</div><div class="progress-track"><i style="width:72%"></i></div><small class="muted">A fresh code every 30 seconds</small></div>`).join('')}<div class="recovery-chip">${icon('backup',28)}<div><strong>Plan for your next phone.</strong><small>One encrypted backup. Android + web.</small></div></div><div class="hero-display-bottom">${icon('lock',16)} The real vault starts empty. Your secrets stay yours.</div></div></section><div class="trust-band wrap"><span>Built around the essentials</span><strong>OFFLINE CODES</strong><strong>ENCRYPTED RECOVERY</strong><strong>ANDROID + WEB</strong><strong>NO ADS</strong></div><section id="features" class="features wrap"><div class="section-top"><div><div class="eyebrow">LESS FRICTION. MORE CONTROL.</div><h2>More than a list<br>of six-digit numbers.</h2></div><p>Less hunting for codes. More control over your next sign-in.</p></div><div class="feature-grid">${[['folder','A place for everything.','Organize accounts in folders. Favorite the ones you reach for every day.'],['heart','Know what needs attention.','Track saved service recovery codes and whether your vault needs a fresh backup.'],['monitor','Your phone. Your browser.','Generate codes in either place. Transfer accounts using the same encrypted backup format.']].map(([i,h,p])=>`<article>${icon(i,30)}<h3>${h}</h3><p>${p}</p></article>`).join('')}</div></section><section id="recovery" class="recovery-section"><div class="wrap recovery-layout"><div><div class="eyebrow">RECOVERY IS PART OF SECURITY.</div><h2>New phone?<br>Keep your way in.</h2><p>Make an encrypted backup. Restore on a trusted device. Test a real service sign-in before removing the original copy.</p><a href="#vault" class="button mint">Start with your vault</a></div><ol class="recovery-steps">${[['01','Create a protected copy','Setup keys are encrypted before your file leaves this device.'],['02','Restore and review','Preview accounts. Identical entries are skipped.'],['03','Test before you switch','Check a real login and keep the backup password safe.']].map(([n,h,p])=>`<li><span>${n}</span><div><h3>${h}</h3><p>${p}</p></div></li>`).join('')}</ol></div></section><section id="faq" class="faq wrap"><div><div class="eyebrow">CLEAR ANSWERS</div><h2>Security should<br>make sense.</h2></div><div class="faq-list">${[['Where are my accounts stored?','Encrypted in this browser on this device. Android uses Keystore. No cloud sync in this edition. Clearing browser data or uninstalling can remove accounts.'],['Does it work offline?','Codes are generated locally. Once the website’s offline cache is ready, it can reopen without internet. Keep your device clock accurate.'],['Can I reset a forgotten password?','No. Keep a password-encrypted backup and your service recovery codes. Losing every copy requires recovery through each service.'],['Does web support fingerprint unlock?','Web uses a vault password. Android supports device credentials or strong biometrics. A browser cannot reliably block screenshots.'],['Does it enable 2FA automatically?','Enable 2FA in each service first. Add the QR or setup key here, then verify the code at that service. TOTP codes are not phishing-resistant.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></section><section class="final-cta wrap"><div>${icon('shield',36)}<h2>Own your next<br>sign-in.</h2></div><a class="button dark" href="#vault">Open Sentinel</a></section></main><footer class="wrap">${brand}<span>Designed for your next sign-in.</span><a href="#vault">Web vault</a><button class="link-button" data-theme>Change appearance</button></footer></div>`;bindTheme();document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>startDemo().catch(ex=>toast(ex.message)));}
function lock(){focusId=null;focusMode=false;epoch++;session=null;modal=null;busy=false;query='';document.querySelectorAll('dialog').forEach(d=>{d.close();d.remove();});if(location.hash==='#vault')renderVault();}
function unlockScreen(){const exists=!!readEnvelope();root.innerHTML=`<div class="unlock-page"><header class="site-header wrap">${brand}<a href="#home">Back to website</a></header><main class="unlock-layout"><div class="unlock-intro"><div class="eyebrow">YOUR BROWSER. YOUR VAULT.</div><h1>A protected place<br>for your <span>next sign-in.</span></h1><p>Your accounts stay encrypted on this device. Unlock with your password and use codes in one focused workspace.</p><div class="unlock-benefits"><div>${icon('folder')} Folders and favorites</div><div>${icon('backup')} Android-compatible backups</div></div></div><section class="unlock-card"><span class="unlock-symbol">${icon('shield',40)}</span><h2>${exists?'Welcome back.':'Create your vault.'}</h2><p>${exists?'Enter your vault password.':'Choose a unique password of at least 12 characters. There is no password reset.'}</p><form id="unlock-form"><label>Vault password<input type="password" name="password" minlength="12" required autocomplete="${exists?'current-password':'new-password'}"></label>${exists?'':'<label>Confirm password<input name="confirm" type="password" minlength="12" required autocomplete="new-password"></label>'}<p class="form-error" id="unlock-error" role="alert"></p><button class="button dark full" type="submit">${exists?'Unlock vault':'Create encrypted vault'}</button></form><button class="button full demo-launch" id="unlock-demo">Explore demo first</button><p class="fine-print">Use a trusted private browser. Clearing browser data removes this vault. Keep an encrypted backup.</p></section></main></div>`;document.getElementById('unlock-demo').onclick=()=>startDemo().catch(ex=>toast(ex.message));document.getElementById('unlock-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const f=e.target,b=f.querySelector('button'),token=epoch;b.disabled=true;b.textContent='Opening your protected vault…';try{const envelope=readEnvelope(),password=f.password.value;if(!envelope&&password!==f.confirm.value)throw Error('Passwords do not match.');const salt=envelope?unbase64(envelope.salt):random(16),key=await deriveKey(password,salt),data=envelope?await decryptJSON(envelope,key):{accounts:[],lastBackup:null,changedAt:Date.now()};if(token!==epoch)return;if(!envelope)vaultWrite(JSON.stringify(await encryptJSON(data,key,salt)));session={key,salt,data,stored:vaultRead()};f.password.value='';busy=false;renderVault();}catch(ex){busy=false;document.getElementById('unlock-error').textContent=ex.message;b.disabled=false;b.textContent=exists?'Unlock vault':'Create encrypted vault';}};}
function bindTheme(){document.querySelectorAll('button[data-theme]').forEach(b=>b.onclick=()=>{theme=theme==='light'?'dark':'light';document.documentElement.dataset.theme=theme;localStorage.setItem('sentinel.preferences',JSON.stringify({theme}));});}
function route(){if(location.hash==='#reset-password'){if(session)lock();resetAccountPassword();}else if(['#signin','#signup','#forgot-password'].includes(location.hash)){if(session)lock();authScreen(location.hash.slice(1));}else if(location.hash==='#vault')renderVault();else{if(session)lock();landing();if(location.hash&&location.hash!=='#home')requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView({behavior:'smooth'}));}}
window.addEventListener('hashchange',route);document.addEventListener('visibilitychange',()=>{if(document.hidden&&session)lock();});window.addEventListener('pagehide',lock);

async function commit(data){if(busy||!session)throw Error('Please finish the current action.');busy=true;const current=session,token=epoch;try{const envelope=await encryptJSON(data,current.key,current.salt);if(token!==epoch||current!==session)throw Error('Vault locked. Unlock and try again.');if(current.stored!==vaultRead()){lock();throw Error('Vault changed in another tab. Unlock again.');}const stored=JSON.stringify(envelope);vaultWrite(stored);current.stored=stored;current.data=data;}finally{busy=false;}}
async function change(fn){const data=structuredClone(session.data);fn(data);data.changedAt=Date.now();await commit(data);renderVault();}
function dialog(title,body,bind){document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.innerHTML=`<div class="dialog-heading"><h2>${title}</h2><button class="icon-button" aria-label="Close">${icon('close')}</button></div>${body}<p class="form-error" role="alert"></p>`;document.body.append(d);d.querySelector('.dialog-heading button').onclick=()=>d.close();d.addEventListener('close',()=>{d.cleanup?.();d.remove();});d.showModal();bind?.(d);return d;}
const field=(label,name,type='text',value='')=>`<label>${label}<input name="${name}" type="${type}" value="${escape(value)}" required ${type==='password'?'autocomplete="new-password"':''}></label>`;
function runForm(d,fn){d.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('[type=submit]');b.disabled=true;try{await fn(e.target);d.close();}catch(ex){d.querySelector('.form-error').textContent=ex.message;b.disabled=false;}};}
function addAccount(prefill=null){dialog(prefill?'Review scanned account':'Add an account',`<p>Enable two-factor authentication at the service, then add its setup key here.</p>${!prefill?'<div class="dialog-actions"><button class="button" id="scan">Scan QR</button><label class="button">QR image<input type="file" id="qr-file" accept="image/*" hidden></label></div>':''}<form>${field('Service / issuer','issuer','text',prefill?.issuer||'')}${field('Account name','label','text',prefill?.label||'')}${!prefill?field('Setup key (Base32)','secret'):''}${folderField(filter!=='All accounts'&&filter!=='Favorites'&&filter!=='Recovery check'?filter:'Personal')}<details><summary>Advanced settings</summary><label>Algorithm<select name="algorithm"><option>SHA1</option><option>SHA256</option><option>SHA512</option></select></label><label>Digits<select name="digits"><option>6</option><option>8</option></select></label><label>Period (seconds)<input name="period" type="number" min="15" max="120" value="30"></label></details><p>After saving, enter a generated code on the service to finish setup.</p><button class="button dark full" type="submit">Save account</button></form>`,d=>{if(prefill){d.querySelector('[name=algorithm]').value=prefill.algorithm;d.querySelector('[name=digits]').value=prefill.digits;d.querySelector('[name=period]').value=prefill.period;}runForm(d,async f=>{const a=validate({id:crypto.randomUUID(),issuer:f.issuer.value.trim(),label:f.label.value.trim(),secret:prefill?.secret||base64(decodeBase32(f.secret.value)),algorithm:f.algorithm.value,digits:Number(f.digits.value),period:Number(f.period.value),folder:validFolder(f.folder.value),favorite:false,recoverySaved:false});if(session.data.accounts.some(x=>sameAccount(x,a)))throw Error('This setup key already exists in your vault.');await change(data=>{if(data.accounts.length>=1000)throw Error('Account limit reached.');data.accounts.push(a);});});d.querySelector('#scan')?.addEventListener('click',()=>{d.close();scanQR();});d.querySelector('#qr-file')?.addEventListener('change',async e=>{try{await loadModule('jsqr');const file=e.target.files[0];if(!file||file.size>10*1024*1024)throw Error('Choose an image under 10 MB.');const bitmap=await createImageBitmap(file);const c=document.createElement('canvas'),scale=Math.min(1,1500/Math.max(bitmap.width,bitmap.height));c.width=bitmap.width*scale;c.height=bitmap.height*scale;const ctx=c.getContext('2d');ctx.drawImage(bitmap,0,0,c.width,c.height);bitmap.close();const pixels=ctx.getImageData(0,0,c.width,c.height),qr=jsQR(pixels.data,c.width,c.height);if(!qr)throw Error('No readable QR code found.');const account=parseProvisioning(qr.data);d.close();addAccount(account);}catch(ex){d.querySelector('.form-error').textContent=ex.message;}});});}
function scanQR(){const d=dialog('Scan setup QR','<p>Point the camera at the service’s authenticator QR code. Images stay on your device.</p><video autoplay playsinline muted></video><p id="camera-status" role="status">Starting camera…</p><div class="dialog-actions"><label class="button" for="scan-image">Choose QR image</label><input type="file" id="scan-image" accept="image/*" hidden><button class="button" id="scan-manual">Manual entry</button></div>');let stream,frame;d.cleanup=()=>{cancelAnimationFrame(frame);stream?.getTracks().forEach(t=>t.stop());};d.querySelector('#scan-manual').onclick=()=>{d.close();addAccount();};d.querySelector('#scan-image').onchange=async e=>{try{const current=session,a=await readQRImage(e.target.files[0]);if(!d.open||session!==current)return;d.close();addAccount(a);}catch(ex){d.querySelector('.form-error').textContent=ex.message;}};const fail=()=>{if(d.open)d.querySelector('#camera-status').textContent='Camera unavailable or permission denied. Choose a QR image or use manual entry.';};if(!navigator.mediaDevices?.getUserMedia){fail();return;}loadModule('jsqr').then(()=>navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}})).then(async media=>{stream=media;if(!d.open){d.cleanup();return;}const v=d.querySelector('video');v.srcObject=media;await v.play();if(!d.open)return;d.querySelector('#camera-status').textContent='Camera ready. Keep the QR code inside the frame.';const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');const tick=()=>{if(!d.open||!session)return;canvas.width=v.videoWidth;canvas.height=v.videoHeight;if(canvas.width){ctx.drawImage(v,0,0);const img=ctx.getImageData(0,0,canvas.width,canvas.height),qr=jsQR(img.data,canvas.width,canvas.height);if(qr){try{const account=parseProvisioning(qr.data);d.close();addAccount(account);return;}catch(ex){d.querySelector('#camera-status').textContent=ex.message;}}}frame=requestAnimationFrame(tick);};tick();}).catch(fail);}
function editAccount(id){const a=session.data.accounts.find(a=>a.id===id);if(!a)return;dialog('Account details',`<form>${field('Service','issuer','text',a.issuer)}${field('Account name','label','text',a.label)}${folderField(a.folder||'Personal')}${switchField('favorite','Favorite account','Keep this account in your Favorites view.',a.favorite)}${switchField('recovery','Recovery codes saved','I saved this service’s recovery codes elsewhere.',a.recoverySaved)}<p>Sentinel records this checklist item, not the recovery codes themselves.</p><button class="button dark full" type="submit">Save changes</button></form><button class="danger" id="delete">Delete account</button>`,d=>{runForm(d,async f=>change(data=>{const record=data.accounts.find(x=>x.id===id);record.issuer=f.issuer.value.trim();record.label=f.label.value.trim();record.folder=validFolder(f.folder.value);record.favorite=f.favorite.checked;record.recoverySaved=f.recovery.checked;validate(record);}));d.querySelector('#delete').onclick=()=>{d.close();deleteAccount(id);};});}
function download(bytes,name){const url=URL.createObjectURL(new Blob([bytes],{type:'application/octet-stream'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function backup(){dialog('Create an encrypted backup',`<p>Works with Sentinel on Android and web. Accounts and setup keys are included. Folders, favorites and checklist items are not included in this portable format.</p><form>${field('Backup password (12+ characters)','password','password')}${field('Confirm password','confirm','password')}<p>Keep this password separately. It cannot be reset.</p><button class="button dark full" type="submit">Download encrypted backup</button></form>`,d=>runForm(d,async f=>{if(f.password.value!==f.confirm.value)throw Error('Passwords do not match.');const current=session,token=epoch,bytes=await exportPortable(current.data.accounts,f.password.value);if(token!==epoch||session!==current)throw Error('Vault locked. Try again.');const data=structuredClone(current.data);data.lastBackup=Date.now();await commit(data);download(bytes,'sentinel-'+new Date().toISOString().slice(0,10)+'.sentinel');f.password.value='';renderVault();toast('Backup downloaded. Test restoring the file before relying on it.');}));}
function restore(){dialog('Restore encrypted backup',`<p>Existing accounts stay in place. You will review accounts before importing.</p><form><label>Sentinel backup<input type="file" name="file" required accept=".sentinel,.bin"></label>${field('Backup password','password','password')}<button class="button dark full" type="submit">Decrypt and review</button></form>`,d=>{d.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{const file=f.file.files[0];if(file.size>10*1024*1024)throw Error('Backup exceeds 10 MB.');const token=epoch,accounts=await importPortable(new Uint8Array(await file.arrayBuffer()),f.password.value);if(!session||token!==epoch)throw Error('Vault locked. Try again.');d.close();const added=accounts.filter(a=>!session.data.accounts.some(b=>sameAccount(a,b)));dialog('Review restore',`<p>${added.length} new accounts. ${accounts.length-added.length} identical accounts skipped.</p><div class="restore-list">${added.map(a=>`<p><strong>${escape(a.issuer)}</strong><br>${escape(a.label)}</p>`).join('')||'<p>No new accounts to import.</p>'}</div><button class="button dark full" id="import">Import reviewed accounts</button>`,review=>review.querySelector('#import').onclick=async()=>{try{await change(data=>{if(data.accounts.length+added.length>1000)throw Error('Account limit reached.');data.accounts.push(...added.map(a=>({...a,id:crypto.randomUUID()})));});review.close();toast('Accounts restored. Test a sign-in before deleting your original copy.');}catch(ex){review.querySelector('.form-error').textContent=ex.message;}});}catch(ex){d.querySelector('.form-error').textContent=ex.message;b.disabled=false;}};});}
function renderVault(){if(!session){unlockScreen();return;}const all=session.data.accounts,folders=folderNames(),title=view==='recovery'?'Recovery check':filter;root.innerHTML=`<div class="workspace"><aside class="sidebar">${brand}<div class="sidebar-label">WORKSPACE</div>${[['All accounts','grid'],['Favorites','star'],['Recovery check','heart']].map(([name,i])=>`<button class="nav-item ${title===name?'active':''}" data-nav="${name}">${icon(i)} ${name}</button>`).join('')}<div class="folder-heading"><div class="sidebar-label">YOUR FOLDERS</div><button class="icon-button" id="new-folder" aria-label="Create folder">${icon('plus',18)}</button></div>${folders.map(f=>`<div class="folder-row"><button class="nav-item ${filter===f?'active':''}" data-folder="${escape(f)}">${icon('folder')} <span>${escape(f)}</span><small>${all.filter(a=>(a.folder||'Personal')===f).length}</small></button><button class="icon-button" data-manage-folder="${escape(f)}" aria-label="Manage folder ${escape(f)}">${icon('settings',16)}</button></div>`).join('')}<div class="sidebar-bottom"><div class="local-note">${icon('lock',18)}<div><strong>Encrypted on this device</strong><small>Local codes. Encrypted storage.</small></div></div><button class="nav-item" id="restore-button">${icon('download')} Restore backup</button><button class="nav-item" id="account-login">${authIdentity?"Sign out":"Sign in / sign up"}</button><button class="nav-item" id="lock-button">${icon('lock')} Lock vault</button></div></aside><main class="workspace-main"><header class="workspace-bar"><span>Workspace / ${escape(title)} ${authIdentity?.demo?" · DEMO":authIdentity?" · "+escape(authIdentity.email||"Signed in"):" · Local mode"}</span><div><button class="icon-button" data-theme aria-label="Change appearance">${icon('sun')}</button><button class="icon-button" id="privacy" aria-label="Toggle code visibility">${icon('eye')}</button></div></header><div class="workspace-content"><div class="dashboard-heading"><div><div class="eyebrow">YOUR EVERYDAY SECURITY</div><h1>${escape(title)} <span class="count-badge">${all.length}</span></h1><p>Your codes. Right where you need them.</p></div><button class="button dark" id="add-button">${icon('plus',18)} Add account</button></div><div class="workspace-banner">${icon('backup',24)}<div><strong>${session.data.lastBackup?'Your recovery copy deserves a check.':'Make recovery part of your routine.'}</strong><p>${session.data.lastBackup?'Last export: '+new Date(session.data.lastBackup).toLocaleDateString()+'. '+(session.data.changedAt>session.data.lastBackup?'Accounts have changed since.':'Test the file on a trusted device.'):'Create a backup before relying on your vault.'}</p></div><button class="text-link" id="backup-button">Create backup</button></div>${view==='recovery'?`<section class="health-card"><h2>${all.filter(a=>a.recoverySaved).length} of ${all.length} accounts checked</h2><p>Save each service’s recovery codes somewhere safe. Mark that step in account details. This checklist cannot verify that those codes are valid.</p><p>Check that your device uses automatic date and time. An incorrect clock causes incorrect codes.</p><label class="attention-filter"><input type="checkbox" id="needs-attention" ${needsAttention?'checked':''}> Show only accounts needing recovery codes</label></section>`:''}<p class="clock-warning" id="clock-warning" ${clockShift?'':'hidden'}>Your device clock changed. Check automatic date and time if codes stop working. Sentinel has not changed your clock.</p><div class="toolbar"><label class="search-field">${icon('search',20)}<input id="search" type="search" value="${escape(query)}" placeholder="Search accounts" aria-label="Search accounts"></label><button class="focus-button ${focusMode?'active':''}" id="focus-mode" aria-pressed="${focusMode}">${icon('eye',16)} Focus mode ${focusMode?'on':'off'}</button></div><label class="smart-copy"><input type="checkbox" id="smart-copy" ${smartCopy?'checked':''}> Copy fresh: wait for the next code when fewer than 6 seconds remain</label><p class="focus-hint" ${focusMode?'':'hidden'}>Choose one account to reveal. Other codes stay hidden while Focus mode is on.</p><div id="account-list" class="account-grid"></div></div></main><div class="add-dock"><div class="add-menu" id="add-menu" hidden><button id="add-manual">${icon('settings',20)}<span>Manual entry<small>Enter a setup key</small></span></button><button id="add-qr">${icon('qr',20)}<span>Scan QR code<small>Camera or QR image</small></span></button></div><button class="floating-add" id="floating-add" aria-label="Add account options" aria-expanded="false" aria-controls="add-menu">${icon('plus',28)}</button></div></div>`;bindWorkspaceExtras();document.getElementById('account-login').onclick=async()=>{if(authIdentity)await accountSignOut();else location.hash='#signin';};document.getElementById('lock-button').onclick=lock;document.getElementById('add-button').onclick=toggleAddMenu;document.getElementById('backup-button').onclick=backup;document.getElementById('restore-button').onclick=restore;document.getElementById('privacy').onclick=()=>{hideCodes=!hideCodes;drawAccounts();};document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{filter=b.dataset.nav;view=filter==='Recovery check'?'recovery':'accounts';renderVault();});document.querySelectorAll('[data-folder]').forEach(b=>b.onclick=()=>{filter=b.dataset.folder;view='accounts';renderVault();});document.getElementById('search').oninput=e=>{query=e.target.value;drawAccounts();};bindTheme();drawAccounts();}
let hideCodes=false;
function drawAccounts(){if(!session)return;const accounts=session.data.accounts.filter(a=>(view==='recovery'||filter==='All accounts'||filter==='Favorites'&&a.favorite||filter===(a.folder||'Personal'))&&(!needsAttention||view!=='recovery'||!a.recoverySaved)&&`${a.issuer} ${a.label}`.toLowerCase().includes(query.toLowerCase()));const list=document.getElementById('account-list');if(!list)return;list.innerHTML=accounts.map(a=>`<article class="token-card ${focusMode&&focusId===a.id?'focused':''}"><div class="account-line"><span class="service-avatar">${escape((a.issuer||a.label)[0].toUpperCase())}</span><div><strong>${escape(a.issuer||'Account')}</strong><small>${escape(a.label)}</small></div><button class="icon-button" data-edit="${a.id}" aria-label="Edit ${escape(a.issuer||a.label)}">${icon('settings',18)}</button></div>${focusMode?`<button class="focus-reveal" data-focus="${a.id}" aria-pressed="${focusId===a.id}">${focusId===a.id?'✓ Account in focus':'Reveal this account'}</button>`:''}<button class="live-code" data-copy="${a.id}" aria-label="Copy code for ${escape(a.issuer||a.label)}">••• •••</button><div class="progress-track"><i data-progress="${a.id}"></i></div><div class="token-meta"><span>${icon('folder',14)} ${escape(a.folder||'Personal')}</span><span data-time="${a.id}"></span></div><div class="card-actions"><button class="card-action ${a.favorite?'selected':''}" data-favorite="${a.id}" aria-label="Favorite ${escape(a.issuer||a.label)}" aria-pressed="${!!a.favorite}">${icon('star',18)}<span>Favorite</span></button><button class="card-action ${a.recoverySaved?'ready':''}" data-recovery="${a.id}" aria-label="Recovery saved for ${escape(a.issuer||a.label)}" aria-pressed="${!!a.recoverySaved}">${icon('shield',18)}<span>${a.recoverySaved?'Recovery saved':'Recovery needed'}</span></button><button class="card-action" data-drill="${a.id}" aria-label="Recovery drill for ${escape(a.issuer||a.label)}">${icon('heart',18)}</button><button class="card-action delete-action" data-delete="${a.id}" aria-label="Delete ${escape(a.issuer||a.label)}">${icon('trash',18)}</button></div></article>`).join('')||`<section class="empty-state">${icon('shield',55)}<h2>${query?'No matching accounts.':view==='recovery'&&needsAttention?'Your recovery checklist is complete.':'Your space is ready.'}</h2><p>${view==='recovery'&&needsAttention?'You marked recovery codes as saved for each account. Test recovery through its service.':'Add a service’s QR code or setup key to begin.'}</p><button class="button dark" id="empty-add">Add account</button></section>`;list.querySelector('#empty-add')?.addEventListener('click',toggleAddMenu);list.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editAccount(b.dataset.edit));list.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteAccount(b.dataset.delete));list.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>safeChange(data=>{const a=data.accounts.find(a=>a.id===b.dataset.favorite);a.favorite=!a.favorite;}));list.querySelectorAll('[data-recovery]').forEach(b=>b.onclick=()=>safeChange(data=>{const a=data.accounts.find(a=>a.id===b.dataset.recovery);a.recoverySaved=!a.recoverySaved;}));list.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>{focusId=focusId===b.dataset.focus?null:b.dataset.focus;drawAccounts();});list.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>copyFresh(b.dataset.copy));list.querySelectorAll('[data-drill]').forEach(b=>b.onclick=()=>recoveryDrill(b.dataset.drill));updateCodes();}
async function updateCodes(){if(!session||document.hidden)return;const current=session,token=epoch;for(const a of current.data.accounts){const b=document.querySelector(`[data-copy="${a.id}"]`);if(!b)continue;const remaining=a.period-Math.floor(Date.now()/1000)%a.period;document.querySelector(`[data-time="${a.id}"]`).textContent=(remaining<=5?'Expires in ':'')+remaining+'s';document.querySelector(`[data-progress="${a.id}"]`).style.width=remaining/a.period*100+'%';if(hideCodes||(focusMode&&focusId!==a.id)){b.textContent='••• •••';continue;}const code=await otp(a);if(token!==epoch||session!==current)return;b.textContent=code.slice(0,code.length/2)+' '+code.slice(code.length/2);}}
setInterval(()=>updateCodes().catch(()=>{}),1000);
window.addEventListener('storage',e=>{if(e.key===vaultStorageKey()&&session){lock();toast('Vault changed in another tab. Unlock again.');}});
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});


let lastActivity=Date.now();["pointerdown","keydown"].forEach(type=>window.addEventListener(type,()=>lastActivity=Date.now()));setInterval(()=>{if(session&&Date.now()-lastActivity>300000){lock();toast("Vault locked after five minutes of inactivity.");}},15000);


let authIdentity=null,demoEnvelope=null,authClient=null;
const DEMO_EMAIL='demo@sentinel.example',DEMO_PASSWORD='SentinelDemo123!';
function vaultStorageKey(){return authIdentity&&!authIdentity.demo?'sentinel.vault.user.'+authIdentity.id:'sentinel.vault';}
function vaultRead(){return authIdentity?.demo?demoEnvelope:localStorage.getItem(vaultStorageKey());}
function vaultWrite(value){if(authIdentity?.demo)demoEnvelope=value;else localStorage.setItem(vaultStorageKey(),value);}
function authScreen(mode='signin'){const signup=mode==='signup',forgot=mode==='forgot-password';root.innerHTML=`<div class="unlock-page auth-page"><header class="site-header wrap">${brand}<a class="text-link" href="#home">Back to website</a></header><main class="unlock-layout"><div class="unlock-intro"><div class="eyebrow">YOUR SECURITY. YOUR SPACE.</div><h1>${signup?'Start with a<br>little more':'Welcome to<br>your'} <span>${signup?'peace of mind.':'safe space.'}</span></h1><p>One Sentinel account. Your own protected workspace. Your vault password stays separate from your account login.</p><div class="auth-art">${icon('shield',80)}<span class="auth-orbit">${icon('lock',26)}</span></div><div class="unlock-benefits"><div>${icon('folder')} Organized around your life</div><div>${icon('backup')} Recovery that travels with you</div></div></div><section class="unlock-card"><div class="eyebrow">SENTINEL ACCOUNT</div><h2>${forgot?'Reset account password.':signup?'Create your account.':'Good to see you.'}</h2><p>${forgot?'We will send a reset link if this email has an account.':signup?'A calmer workspace starts here.':'Sign in to your account, or explore the demo.'}</p>${!forgot?`<div class="social-buttons"><button class="social-button" data-provider="google"><span class="google-mark">G</span> Continue with Google</button><button class="social-button apple" data-provider="apple"><span>●</span> Continue with Apple</button></div><div class="auth-divider"><span>or continue with email</span></div>${!authConfig.url?'<p class="account-status">Account login is not available yet. <a href="#vault">Open a local vault</a> or try the demo below.</p>':''}`:''}<form id="account-form">${signup?'<label>Your name<input name="name" autocomplete="name" maxlength="100" required></label>':''}<label>Email address<input type="email" name="email" autocomplete="email" required maxlength="254" placeholder="you@example.com"></label>${!forgot?`<label>Password<input type="password" name="password" autocomplete="${signup?'new-password':'current-password'}" minlength="12" required placeholder="${signup?'At least 12 characters':'Your account password'}"></label>`:''}${signup?'<label>Confirm password<input name="confirm" type="password" autocomplete="new-password" minlength="12" required></label>':''}<p class="form-error" id="account-error" role="alert"></p><p class="form-success" id="account-success" role="status"></p><button class="button dark full" type="submit">${forgot?'Send reset link':signup?'Create account':'Sign in'} ${icon('lock',16)}</button></form>${!forgot?`<div class="auth-links"><span>${signup?'Already have an account?':'New to Sentinel?'} <a href="#${signup?'signin':'signup'}">${signup?'Sign in':'Create account'}</a></span>${!signup?'<a href="#forgot-password">Forgot password?</a>':''}</div><section class="demo-access"><div><strong>Take a look around.</strong><small>A separate demo with public test accounts.</small></div><button class="button" id="try-demo">Try demo</button><details><summary>Demo credentials</summary><p>Email: <code>${DEMO_EMAIL}</code><br>Password: <code>${DEMO_PASSWORD}</code></p></details></section>`:'<p><a href="#signin">Back to sign in</a></p>'}<p class="fine-print">Account sign-in does not decrypt or sync your vault. Keep its separate password and a tested backup. ${!authConfig.url?'Real account login is awaiting backend setup.':''}</p><a class="text-link local-mode-link" href="#vault" id="local-mode">Continue with a local vault</a></section></main></div>`;
 document.getElementById('local-mode').onclick=()=>{if(authIdentity){lock();authIdentity=null;demoEnvelope=null;}};
 document.querySelectorAll('[data-provider]').forEach(b=>b.onclick=async()=>{const error=document.getElementById('account-error');try{if(!authClient)throw Error('Social login is awaiting authentication backend setup. You can try the demo or use the local vault.');const provider=b.dataset.provider;if(!authConfig[provider+'Enabled'])throw Error((provider==='apple'?'Apple':'Google')+' sign-in is awaiting provider credentials.');const {error:err}=await authClient.auth.signInWithOAuth({provider,options:{redirectTo:location.origin+'/?auth=callback#signin'}});if(err)throw err;}catch(ex){error.textContent=ex.message;}});
 document.getElementById('try-demo')?.addEventListener('click',()=>startDemo());
 document.getElementById('account-form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button'),error=document.getElementById('account-error'),success=document.getElementById('account-success');error.textContent='';success.textContent='';b.disabled=true;try{const email=f.email.value.trim().toLowerCase();if(!signup&&!forgot&&email===DEMO_EMAIL){if(f.password.value!==DEMO_PASSWORD)throw Error('The demo password is incorrect.');await startDemo();return;}if(!authClient)throw Error('Account login is not available yet. Your local vault and demo are ready to use.');if(forgot){const {error:err}=await authClient.auth.resetPasswordForEmail(email,{redirectTo:location.origin+'/?auth=recovery#reset-password'});if(err)throw err;success.textContent='If an account exists, check its email for a reset link.';}else if(signup){if(f.password.value!==f.confirm.value)throw Error('Passwords do not match.');const {data,error:err}=await authClient.auth.signUp({email,password:f.password.value,options:{data:{display_name:f.name.value.trim()},emailRedirectTo:location.origin+'/?auth=callback#signin'}});if(err)throw err;if(data.session){await acceptAccount(data.user);return;}success.textContent='Check your inbox to confirm your email, then sign in.';}else{const {data,error:err}=await authClient.auth.signInWithPassword({email,password:f.password.value});if(err)throw err;await acceptAccount(data.user);}f.password&&(f.password.value='');}catch(ex){error.textContent=ex.message;}finally{b.disabled=false;}};
}
async function acceptAccount(user){if(!user?.id)throw Error('Sign-in did not return a valid user.');lock();authIdentity={id:user.id,email:user.email,demo:false};demoEnvelope=null;filter='All accounts';view='accounts';location.hash='#vault';renderVault();}
async function accountSignOut(){lock();if(authClient&&!authIdentity?.demo){const {error}=await authClient.auth.signOut();if(error){toast('Could not complete server sign-out. Try again when online.');return;}}authIdentity=null;demoEnvelope=null;location.hash='#signin';authScreen();}
async function startDemo(){lock();authIdentity={id:'demo',email:DEMO_EMAIL,demo:true};const token=epoch,salt=random(16),key=await crypto.subtle.generateKey({name:'AES-GCM',length:256},false,['encrypt','decrypt']);if(token!==epoch)return;const seeds=['Google','GitHub','Design workspace'].map((issuer,i)=>({...parseProvisioning('otpauth://totp/'+encodeURIComponent(issuer)+':demo%40example.test?secret=GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ&issuer='+encodeURIComponent(issuer)),label:'demo@example.test',folder:i?'Work':'Personal',favorite:i===0,recoverySaved:i<2}));const data={accounts:seeds,lastBackup:null,changedAt:Date.now()};demoEnvelope=JSON.stringify(await encryptJSON(data,key,salt));session={key,salt,data,stored:demoEnvelope};filter='All accounts';view='accounts';location.hash='#vault';renderVault();toast('Demo mode uses public test keys. Never add real secrets here.');}
async function initAccountAuth(){route();if(authConfig.url&&authConfig.publishableKey){await loadModule('supabase');authClient=supabase.createClient(authConfig.url,authConfig.publishableKey,{auth:{flowType:'pkce',storage:sessionStorage,persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});authClient.auth.onAuthStateChange((event,current)=>{if(event==='SIGNED_OUT'&&authIdentity&&!authIdentity.demo){lock();authIdentity=null;location.hash='#signin';}if(event==='PASSWORD_RECOVERY'){location.hash='#reset-password';resetAccountPassword();}});try{const {data,error}=await Promise.race([authClient.auth.getUser(),new Promise(resolve=>setTimeout(()=>resolve({data:{user:null},error:Error("Timeout")}),6000))]);if(!error&&data.user){authIdentity={id:data.user.id,email:data.user.email,demo:false};}}catch{}const params=new URLSearchParams(location.search);if(params.has('code')||params.has('auth'))history.replaceState({},'',location.pathname+location.hash);}route();}

function resetAccountPassword(){root.innerHTML=`<main class="unlock-layout"><section class="unlock-card">${brand}<h2>New account password</h2><p>This resets your account login, not the vault encryption password.</p><form id="reset-form">${field('New password (12+ characters)','password','password')}${field('Confirm new password','confirm','password')}<p class="form-error" role="alert"></p><button class="button dark full" type="submit">Update password</button></form></section></main>`;document.getElementById('reset-form').onsubmit=async e=>{e.preventDefault();const f=e.target;try{if(!authClient||f.password.value.length<12||f.password.value!==f.confirm.value)throw Error('Enter matching passwords of at least 12 characters.');const {error}=await authClient.auth.updateUser({password:f.password.value});if(error)throw error;await accountSignOut();toast('Account password updated. Sign in again.');}catch(ex){f.querySelector('.form-error').textContent=ex.message;}};}

let focusMode=false,focusId=null,needsAttention=false;
const folderNames=()=>[...new Set(['Personal',...(session.data.folders||[]),...session.data.accounts.map(a=>a.folder||'Personal')])].sort((a,b)=>a.localeCompare(b));
function validFolder(value){const name=value.trim()||'Personal';if(name.length>64||/[\x00-\x1f]/.test(name))throw Error('Use a folder name of 1–64 characters.');if(['All accounts','Favorites','Recovery check'].includes(name))throw Error('Choose a different folder name.');return name;}
function folderField(value){return `<label>Folder<input name="folder" value="${escape(value)}" maxlength="64" list="folder-options"><datalist id="folder-options">${folderNames().map(f=>`<option value="${escape(f)}"></option>`).join('')}</datalist></label>`;}
function switchField(name,title,description,checked){return `<label class="switch-row"><span class="switch-control"><input type="checkbox" role="switch" name="${name}" ${checked?'checked':''}><span class="switch-track" aria-hidden="true"><span>✓</span></span></span><span class="switch-copy"><strong>${title}</strong><small>${description}</small></span></label>`;}
async function safeChange(fn){try{await change(fn);}catch(ex){toast(ex.message);}}
function deleteAccount(id){const a=session.data.accounts.find(a=>a.id===id);if(!a)return;dialog('Delete this account?',`<p>Remove <strong>${escape(a.issuer||a.label)}</strong> from this vault? This does not disable 2FA at the service. Check that you can sign in with another copy or the service’s recovery codes.</p><div class="dialog-actions"><button class="button" id="cancel-delete">Keep account</button><button class="button danger-fill" id="confirm-delete">Delete account</button></div>`,d=>{d.querySelector('#cancel-delete').onclick=()=>d.close();d.querySelector('#confirm-delete').onclick=async e=>{e.target.disabled=true;try{await change(data=>data.accounts=data.accounts.filter(a=>a.id!==id));d.close();}catch(ex){d.querySelector('.form-error').textContent=ex.message;e.target.disabled=false;}};});}
function createFolder(){dialog('Create a folder',`<p>Give your accounts a place of their own. Empty folders are saved in your encrypted vault.</p><form>${field('Folder name','folder')}<button class="button dark full" type="submit">Create folder</button></form>`,d=>runForm(d,async f=>{const name=validFolder(f.folder.value);if(folderNames().some(x=>x.toLowerCase()===name.toLowerCase()))throw Error('That folder already exists.');if(folderNames().length>=100)throw Error('This vault supports up to 100 folders.');await change(data=>{data.folders=[...(data.folders||[]),name];});filter=name;view='accounts';renderVault();}));}
function manageFolder(name){dialog('Manage folder',`<form>${field('Folder name','folder','text',name)}<button class="button dark full" type="submit">Rename folder</button></form>${name!=='Personal'?'<button class="danger" id="remove-folder">Remove folder</button><p>Accounts in this folder will move to Personal. Their setup keys stay in your vault.</p>':'<p>Personal is the default folder and cannot be renamed or removed.</p>'}`,d=>{if(name==='Personal'){d.querySelector('input').disabled=true;d.querySelector('[type=submit]').disabled=true;}runForm(d,async f=>{const next=validFolder(f.folder.value);if(next!==name&&folderNames().some(x=>x.toLowerCase()===next.toLowerCase()))throw Error('That folder already exists.');await change(data=>{data.folders=[...new Set([...(data.folders||[]).filter(x=>x!==name),next])];data.accounts.forEach(a=>{if(a.folder===name)a.folder=next;});});if(filter===name)filter=next;renderVault();});d.querySelector('#remove-folder')?.addEventListener('click',()=>{d.close();dialog('Remove folder?',`<p>Accounts in <strong>${escape(name)}</strong> will move to Personal. No accounts will be deleted.</p><button class="button dark full" id="confirm-remove-folder">Move accounts and remove folder</button>`,confirm=>confirm.querySelector('#confirm-remove-folder').onclick=async e=>{e.target.disabled=true;try{await change(data=>{data.folders=(data.folders||[]).filter(f=>f!==name);data.accounts.forEach(a=>{if(a.folder===name)a.folder='Personal';});});if(filter===name)filter='Personal';renderVault();confirm.close();}catch(ex){confirm.querySelector('.form-error').textContent=ex.message;e.target.disabled=false;}});});});}
function toggleAddMenu(){const menu=document.getElementById('add-menu');menu.hidden=!menu.hidden;document.getElementById('floating-add').setAttribute('aria-expanded',String(!menu.hidden));if(!menu.hidden)menu.querySelector('button').focus();}
function closeAddMenu(){const menu=document.getElementById('add-menu');if(menu)menu.hidden=true;document.getElementById('floating-add')?.setAttribute('aria-expanded','false');}
function bindWorkspaceExtras(){document.getElementById('smart-copy').onchange=e=>{smartCopy=e.target.checked;};document.getElementById('new-folder').onclick=createFolder;document.querySelectorAll('[data-manage-folder]').forEach(b=>b.onclick=()=>manageFolder(b.dataset.manageFolder));document.getElementById('floating-add').onclick=toggleAddMenu;document.getElementById('add-manual').onclick=()=>{closeAddMenu();addAccount();};document.getElementById('add-qr').onclick=()=>{closeAddMenu();scanQR();};document.getElementById('focus-mode').onclick=()=>{focusMode=!focusMode;focusId=null;renderVault();};document.getElementById('needs-attention')?.addEventListener('change',e=>{needsAttention=e.target.checked;drawAccounts();});}
document.addEventListener('pointerdown',e=>{if(!e.target.closest('.add-dock,#add-button,#empty-add'))closeAddMenu();});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeAddMenu();});
async function readQRImage(file){await loadModule('jsqr');if(!file||file.size>10*1024*1024)throw Error('Choose an image under 10 MB.');const bitmap=await createImageBitmap(file);try{const c=document.createElement('canvas'),scale=Math.min(1,1500/Math.max(bitmap.width,bitmap.height));c.width=Math.max(1,Math.round(bitmap.width*scale));c.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=c.getContext('2d');ctx.drawImage(bitmap,0,0,c.width,c.height);const pixels=ctx.getImageData(0,0,c.width,c.height),qr=jsQR(pixels.data,c.width,c.height);if(!qr)throw Error('No readable authenticator QR found.');return parseProvisioning(qr.data);}finally{bitmap.close();}}


let smartCopy=false,copyPending=null;
async function copyFresh(id){if(copyPending){toast('A fresh code is already being prepared.');return;}if(!session)return;const current=session,token=epoch,a=current.data.accounts.find(a=>a.id===id);if(!a)return;if(hideCodes||(focusMode&&focusId!==id)){toast('Reveal this account before copying its code.');return;}copyPending=id;const remaining=a.period-Math.floor(Date.now()/1000)%a.period;try{if(smartCopy&&remaining<=5){toast('Waiting '+remaining+'s for a fresh code. Keep Sentinel open.');await new Promise(resolve=>setTimeout(resolve,remaining*1000+120));}if(session!==current||epoch!==token||document.hidden)return;await navigator.clipboard.writeText(await otp(a));toast('Code copied. Clipboard history may retain it.');}catch{toast('Clipboard unavailable. Read the displayed code instead.');}finally{copyPending=null;}}
function recoveryDrill(id){const a=session.data.accounts.find(a=>a.id===id);if(!a)return;dialog('Practice your recovery plan',`<p>For <strong>${escape(a.issuer||a.label)}</strong>, keep this app open while you test a sign-in on another device. Never disable 2FA during this drill.</p><ol class="drill-steps"><li>Locate this service’s recovery codes in your separate safe storage.</li><li>Confirm you have a password-encrypted Sentinel backup and know its password.</li><li>Test a normal sign-in at the real service using a fresh code.</li></ol><p>This is your checklist. Sentinel cannot verify the service sign-in.</p><button class="button dark full" id="drill-complete">I tested my sign-in</button>${a.lastVerifiedAt?`<p>Last marked tested: ${new Date(a.lastVerifiedAt).toLocaleDateString()}</p>`:''}`,d=>{d.querySelector('#drill-complete').onclick=async e=>{e.target.disabled=true;try{await change(data=>{data.accounts.find(x=>x.id===id).lastVerifiedAt=Date.now();});d.close();toast('Drill recorded in your encrypted vault.');}catch(ex){d.querySelector('.form-error').textContent=ex.message;e.target.disabled=false;}};});}
let clockWall=Date.now(),clockMono=performance.now(),clockShift=false;
setInterval(()=>{const wall=Date.now(),mono=performance.now();if(session&&!document.hidden&&Math.abs((wall-clockWall)-(mono-clockMono))>2000){clockShift=true;const warning=document.getElementById('clock-warning');if(warning)warning.hidden=false;}clockWall=wall;clockMono=mono;},2000);

initAccountAuth().catch(()=>{authClient=null;route();toast("Account service unavailable. Your local vault is ready.");});

window.addEventListener('sentinel-account-login',e=>acceptAccount(e.detail).catch(ex=>toast(ex.message)));
